INSERT INTO projects (id, slug, year, category, title, client, service, image, description, full_description, video_url, video_url2, hover_video_url, gallery) VALUES (1, 'expo-irati-2024', '2024', 'Evento', 'DOCUMENTÁRIO EXPO IRATI 2024', 'Prefeitura de Irati', 'Eventos / Produção', '/projects/eventos/capa24EXPO01043.jpg', 'Comissionado pela Prefeitura Municipal de Irati, este documentário é o registro definitivo da ExpoIrati 2024. Nossa produção mobilizou uma estrutura técnica avançada para capturar a magnitude do evento, equilibrando a precisão do agronegócio com a energia dos grandes espetáculos. O resultado é uma narrativa audiovisual que não apenas documenta números, mas preserva a identidade cultural e o crescimento econômico da região em uma obra de alto impacto técnico e institucional.', 'Capturamos a essência e a energia da maior feira do Centro-Sul no documentário oficial da ExpoIrati 2024.', '/projects/expo-irati-2024/DOCUMENTARY_EXPO-001-006.mp4', NULL, NULL, ARRAY['/projects/eventos/24EXPO00973.jpg','/projects/eventos/24EXPO00988.jpg','/projects/eventos/24EXPO01484.jpg','/projects/eventos/24EXPO01378.jpg','/projects/eventos/24EXPO01654.jpg']::text[]);
